import { z } from "zod";

/**
 * A billing session token, generated by the dashboard once per address the
 * employee is picking. Opaque to us — we only pass it through — but bounded,
 * because it lands in a query string on an outbound request.
 */
const sessionTokenSchema = z.string().trim().min(1).max(128);

export const autocompleteQuerySchema = z.object({
  q: z.string().trim().min(1).max(200),
  session_token: sessionTokenSchema,
});

export const autocompleteResponseSchema = z.object({
  data: z.array(
    z.object({
      place_id: z.string(),
      /** Street number and name — the line to show in bold. */
      primary_text: z.string(),
      /** City, region, country — the disambiguating remainder. */
      secondary_text: z.string(),
    }),
  ),
});

export const resolveParamsSchema = z.object({
  place_id: z.string().trim().min(1).max(255),
});

export const resolveQuerySchema = z.object({
  session_token: sessionTokenSchema,
});

export const resolveResponseSchema = z.object({
  place_id: z.string(),
  formatted_address: z.string(),
  latitude: z.number(),
  longitude: z.number(),
});
